/*
 * Sentinel Remote Control Center: the hub's Dashboard, fed from the cloud.
 *
 * The gauges, device cards and charts are the hub's own code
 * (js/hub-dashboard-core.js, generated by tools/sync-hub-dashboard.cjs). This
 * file reads the read-only Firebase dashboard API, reshapes it into the
 * payloads the hub page expects (/api/nodes, /api/history), and replaces the
 * few hub functions that talk to the hub itself.
 *
 * The cloud stores less than the hub knows. Where a field is missing it is
 * derived the way the hub would:
 *  - battery profile (5/12/24 V) from the voltage, unless the cloud sends it;
 *  - operating mode from the spacing of recent readings, unless sent;
 *  - online / late from that mode's schedule, using the hub's thresholds.
 *
 * URL options: ?site=Cotton&hub=Home picks the site/hub; ?demo=1 shows sample data.
 */
'use strict';

const CLOUD = (() => {
  const cfg = window.SENTINEL_CONFIG || {};
  const params = new URLSearchParams(location.search);
  return {
    apiUrl: cfg.apiUrl,
    siteId: cfg.defaultSiteId || 'Cotton',
    hubId: cfg.defaultHubId || 'Home',
    demo: params.get('demo') === '1' || cfg.useMockData === true,
    refreshMs: cfg.liveRefreshIntervalMs || 30000,
  };
})();

// Report spacing per mode, matching the hub (sleep + ~15 s awake).
const MODE_INTERVALS = { LIVE: 25, DIAGNOSTIC: 75, NORMAL: 3615, STORAGE: 21615 };
const RANGE_LIMITS = { '24h': 2000, '7d': 5000, '30d': 10000 };   // cloud row caps per request
const cloudNodes = new Map();   // hub-style numeric id -> cloud node record
const rawHistory = {};          // id -> chronological readings [{t, volts, tempF, probeF, rssi, sequence, status}]
const rangeNotes = {};          // `${range}:${id}` -> note when the cloud capped the rows

// ---------- Cloud access ----------

async function cloudGet(endpoint, params) {
  if (CLOUD.demo) return SentinelDemo.get(endpoint, params);
  const url = new URL(CLOUD.apiUrl + endpoint);
  Object.entries(params).forEach(([k, v]) => url.searchParams.set(k, v));
  const r = await fetch(url, { cache: 'no-store' });
  if (!r.ok) throw new Error('Cloud ' + r.status);
  return r.json();
}

const num = v => (typeof v === 'number' && Number.isFinite(v) ? v : null);

function readingFromCloud(r) {
  const t = Date.parse(r.recordedAt);
  if (!Number.isFinite(t) || num(r.voltage) === null) return null;
  // temperatureF is the onboard SHT40 on current firmware; newer API versions
  // may send internal/external explicitly.
  const onboard = r.internalTemperatureF !== undefined ? num(r.internalTemperatureF) : num(r.temperatureF);
  return {
    t, volts: r.voltage, tempF: onboard, probeF: num(r.externalTemperatureF), humidityRh: num(r.humidityRh),
    rssi: Number.isInteger(r.rssi) ? r.rssi : null, sequence: Number.isInteger(r.sequence) ? r.sequence : 0,
    status: statusFromCloud(r),
  };
}

function statusFromCloud(r) {
  if (Number.isInteger(r.statusCode) && STATUS_CODES[r.statusCode]) return STATUS_CODES[r.statusCode];
  if (r.status === 'NORMAL' || r.status === 'OK') return 'OK';
  return r.status === 'LOW' || r.status === 'CRITICAL' ? r.status : 'OK';
}

async function cloudHistory(nodeId, range) {
  const data = await cloudGet('/dashboard/history', { siteId: CLOUD.siteId, hubId: CLOUD.hubId, nodeId, range });
  return (data.readings || []).map(readingFromCloud).filter(Boolean).sort((a, b) => a.t - b.t);
}

// ---------- Deriving what the cloud doesn't store ----------

function profileFor(volts, sent) {
  if (sent && GAUGE_PROFILES[sent]) return sent;
  if (!Number.isFinite(volts)) return '12V';
  return volts < 8 ? '5V' : volts > 18 ? '24V' : '12V';
}

// Median spacing of recent reports, snapped to the nearest mode.
function modeFor(readings, sent) {
  if (sent && MODE_INTERVALS[sent]) return sent;
  const recent = readings.slice(-20);
  const gaps = [];
  for (let i = 1; i < recent.length; i++) gaps.push((recent[i].t - recent[i - 1].t) / 1000);
  if (gaps.length < 2) return 'NORMAL';
  gaps.sort((a, b) => a - b);
  const median = gaps[Math.floor(gaps.length / 2)];
  let best = 'NORMAL', bestDiff = Infinity;
  for (const [mode, s] of Object.entries(MODE_INTERVALS)) {
    const diff = Math.abs(Math.log(median / s));
    if (diff < bestDiff) { bestDiff = diff; best = mode; }
  }
  return best;
}

// Hub thresholds (config.h): late = 1.5 x interval + 30 s; offline = 3 x interval + 60 s, at least 15 min.
function healthFor(ageSeconds, intervalSeconds) {
  if (!Number.isFinite(ageSeconds)) return { online: false, late: false };
  const late = intervalSeconds * 1.5 + 30;
  const offline = Math.max(intervalSeconds * 3 + 60, 15 * 60);
  return { online: ageSeconds < offline, late: ageSeconds >= late && ageSeconds < offline };
}

function idFor(nodeId, used) {
  const n = parseInt(String(nodeId).replace(/\D/g, ''), 10);
  if (Number.isFinite(n) && n > 0 && !used.has(n)) return n;
  let i = 1;
  while (used.has(i)) i++;
  return i;
}

const fToCx10 = f => (Number.isFinite(f) ? Math.round((f - 32) * 50 / 9) : null);   // °F -> °C x10

// ---------- Hub payloads built from cloud data ----------

function hubNode(id, cloud, now) {
  const latest = cloud.latest ? readingFromCloud(cloud.latest) : null;
  const seen = Date.parse(cloud.lastSeenAt || (cloud.latest && cloud.latest.recordedAt));
  const ageSeconds = Number.isFinite(seen) ? Math.max(0, Math.round((now - seen) / 1000)) : null;
  const history = rawHistory[id] || [];
  const mode = modeFor(history, cloud.latest && cloud.latest.operatingMode);
  const interval = MODE_INTERVALS[mode];
  const volts = latest ? latest.volts : NaN;
  return {
    id, rev: cloud.latest ? cloud.latest.recordedAt : '', cloudNodeId: cloud.nodeId,
    name: cloud.displayName || cloud.nodeId, deviceUid: cloud.deviceUid || '',
    ...healthFor(ageSeconds, interval), waiting: false, expectedIntervalSeconds: interval,
    volts, assetProfile: profileFor(volts, cloud.latest && cloud.latest.assetProfile), operatingMode: mode,
    status: latest ? latest.status : 'UNKNOWN', rssi: latest ? latest.rssi : null, ageSeconds,
    tempF: latest ? latest.tempF : null, humidityRh: latest ? latest.humidityRh : null,
    externalTempF: latest ? latest.probeF : null,
    externalTempStatus: latest && Number.isFinite(latest.probeF) ? 'OK' : 'NOT PRESENT',
    firmware: cloud.latest && cloud.latest.firmwareVersion || '', divider: null, dividerPending: false,
    modeInferred: !(cloud.latest && cloud.latest.operatingMode),
  };
}

// Hub "recent" format: [ageSeconds, mV, tempCx10, rhX10, probeCx10, probeStatus, rssi, sequence, statusCode]
function recentPayload(id) {
  const now = Date.now();
  const codes = { OK: 0, LOW: 1, CRITICAL: 2 };
  const points = (rawHistory[id] || []).slice(-96).map(p => [
    Math.max(0, Math.round((now - p.t) / 1000)), Math.round(p.volts * 1000), fToCx10(p.tempF),
    Number.isFinite(p.humidityRh) ? Math.round(p.humidityRh * 10) : null, fToCx10(p.probeF),
    Number.isFinite(p.probeF) ? 1 : 0, p.rssi, p.sequence, codes[p.status] ?? 255]);
  return { nodeId: id, range: 'recent', points };
}

// Hub hourly format: [hourStartSeconds, mVavg, mVmin, mVmax, tempCx10, probeCx10, rssi, count]
function hourlyPayload(readings, range) {
  const buckets = new Map();
  for (const p of readings) {
    const hour = Math.floor(p.t / 3600000);
    if (!buckets.has(hour)) buckets.set(hour, []);
    buckets.get(hour).push(p);
  }
  const avg = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
  const points = [...buckets.entries()].sort((a, b) => a[0] - b[0]).map(([hour, ps]) => {
    const mv = ps.map(p => p.volts * 1000);
    const temps = ps.map(p => p.tempF).filter(Number.isFinite);
    const probes = ps.map(p => p.probeF).filter(Number.isFinite);
    const rssis = ps.map(p => p.rssi).filter(Number.isFinite);
    return [hour * 3600, Math.round(avg(mv)), Math.round(Math.min(...mv)), Math.round(Math.max(...mv)),
      temps.length ? fToCx10(avg(temps)) : null, probes.length ? fToCx10(avg(probes)) : null,
      rssis.length ? Math.round(avg(rssis)) : null, ps.length];
  });
  return { range, bucketSeconds: 3600, now: Math.floor(Date.now() / 1000), available: true, points };
}

// ---------- Loading ----------

async function loadRecent(n) {
  // The last hour covers fast modes; slower nodes need the day to show a trend.
  let readings = await cloudHistory(n.nodeId, 'live');
  if (readings.length < 12) readings = await cloudHistory(n.nodeId, '24h');
  return readings;
}

async function loadRange(id, range) {
  const cloud = cloudNodes.get(id);
  let readings = await cloudHistory(cloud.nodeId, range);
  const key = range + ':' + id;
  delete rangeNotes[key];
  if (range !== '24h' && readings.length >= RANGE_LIMITS[range]) {
    // The cloud returns the oldest rows first and stops at its cap, so a busy
    // node's most recent days would be missing. Add the last 24 h back in.
    const day = await cloudHistory(cloud.nodeId, '24h');
    const seen = new Set(readings.map(p => p.t));
    readings = readings.concat(day.filter(p => !seen.has(p.t))).sort((a, b) => a.t - b.t);
    rangeNotes[key] = `The cloud returned its first ${RANGE_LIMITS[range].toLocaleString()} readings for this range plus the last 24 hours; hours between may be blank.`;
  }
  return hourlyPayload(readings, range);
}

// Hub function, replaced: history comes from the cloud instead of /api/history.
async function fetchHistory(id, range) {
  return range === 'recent' ? recentPayload(id) : loadRange(id, range);
}

let refreshing = false;
async function refresh() {
  if (refreshing) return;
  refreshing = true;
  const chartInspection = rememberChartInspection();
  try {
    const data = await cloudGet('/dashboard/nodes', { siteId: CLOUD.siteId, hubId: CLOUD.hubId });
    const used = new Set();
    const list = (data.nodes || []).filter(c => c && c.latest);
    const fresh = new Map();
    for (const c of list) {
      const known = [...cloudNodes.entries()].find(([, v]) => v.nodeId === c.nodeId);
      const id = known ? known[0] : idFor(c.nodeId, used);
      used.add(id);
      fresh.set(id, c);
    }
    cloudNodes.clear();
    fresh.forEach((v, k) => cloudNodes.set(k, v));

    // Recent history per node, refetched only when a new reading has arrived.
    await Promise.all([...cloudNodes.entries()].map(async ([id, c]) => {
      const rev = c.latest.recordedAt;
      if (histRev[id] === rev) return;
      try { rawHistory[id] = await loadRecent(c); histRev[id] = rev; } catch (e) { /* keep previous */ }
    }));

    const nodes = buildNodes();
    for (const n of nodes) histories[n.id] = mapRecent(recentPayload(n.id));
    render({ nodes });
    await refreshSelectedRange();
    renderDashboardCards();
    restoreChartInspection(chartInspection);
    setConnection(true);
  } catch (e) {
    setConnection(false);
    if (!latestNodes.length) document.getElementById('dashboardDetail').innerHTML =
      '<div class="empty">The cloud dashboard isn\'t answering right now. Readings will appear when it is back.</div>';
  } finally {
    refreshing = false;
  }
}

function buildNodes() {
  const now = Date.now();
  return [...cloudNodes.entries()].map(([id, c]) => hubNode(id, c, now)).sort((a, b) => a.id - b.id);
}

// Hourly ranges are loaded for the device being viewed (the hub loads all; here
// each one is a cloud request).
async function refreshSelectedRange() {
  if (chartRange === 'recent' || selectedDashboardNode === null) return;
  const n = latestNodes.find(x => x.id === selectedDashboardNode);
  if (!n) return;
  const key = chartRange + ':' + n.id;
  if (rangeRev[key] === n.rev && Date.now() - (rangeAt[key] || 0) < 600000) return;
  try {
    rangeHist[chartRange][n.id] = mapHourly(await fetchHistory(n.id, chartRange), RANGE_HOURS[chartRange]);
    rangeRev[key] = n.rev;
    rangeAt[key] = Date.now();
  } catch (e) { /* the chart shows its loading/empty text */ }
}

// ---------- Hub functions replaced for the cloud page ----------

function render(data) {
  latestNodes = data.nodes || [];
  const online = latestNodes.filter(n => n.online).length;
  const attention = latestNodes.filter(n => n.online && (n.status === 'LOW' || n.status === 'CRITICAL' || n.late)).length;
  const ages = latestNodes.map(n => n.ageSeconds).filter(Number.isFinite);
  const youngest = ages.length ? Math.min(...ages) : null;
  document.getElementById('sumNodes').textContent = latestNodes.length;
  document.getElementById('sumOnline').textContent = online;
  document.getElementById('sumAttention').textContent = attention;
  document.getElementById('sumLast').textContent = youngest === null ? '—' : ageText(youngest).replace(' ago', '');
  document.getElementById('updated').textContent = 'Updated ' + new Date().toLocaleTimeString();
  renderDashboardCards();
}

function selectDashboardNode(id) {
  selectedDashboardNode = id;
  const sel = latestNodes.find(n => n.id === id);
  const detailEl = document.getElementById('dashboardDetail');
  if (detailEl) detailEl.innerHTML = sel ? dashboardCard(sel) : '';
  document.querySelectorAll('#dashboardSummary .miniCard').forEach(el => el.classList.toggle('active', Number(el.dataset.id) === id));
  if (chartRange !== 'recent') refreshSelectedRange().then(renderDashboardCards);
}

function setChartRange(k) {
  if (k === chartRange) return;
  chartRange = k;
  try { localStorage.setItem('sentinelChartRange', k); } catch (e) {}
  renderDashboardCards();
  refreshSelectedRange().then(renderDashboardCards);
}

// Same layout as the hub's stats; drops hub-only rows (voltage divider) and
// marks values the cloud page derives rather than receives.
function statBlock(n) {
  const signal = n.online && Number.isFinite(n.rssi) ? signalQuality(n.rssi) + ' (' + n.rssi + ' dBm)' : '—';
  const probe = Number.isFinite(n.externalTempF)
    ? `<div class="stat">External probe temperature<b>${n.online ? n.externalTempF.toFixed(1) + ' °F' : '—'}</b></div>` : '';
  const onboard = Number.isFinite(n.tempF)
    ? `<div class="stat">Onboard temperature (SHT40)<b>${n.online ? n.tempF.toFixed(1) + ' °F' : '—'}</b></div>` : '';
  return `<div class="stats"><div class="stat">Voltage<b>${n.online ? n.volts.toFixed(2) + ' V' : '—'}</b></div>${probe}${onboard}` +
    `<div class="stat">Operating mode<b>${esc(n.operatingMode)}${n.modeInferred ? ' <small style="font-weight:400;color:var(--muted)">(from report timing)</small>' : ''}</b></div>` +
    `<div class="stat">Signal<b>${signal}</b></div><div class="stat">Expected voltage<b>${esc(n.assetProfile)}</b></div>` +
    `<div class="stat">Last report<b>${Number.isFinite(n.ageSeconds) ? ageText(n.ageSeconds) : '—'}</b></div></div>`;
}

function historyMeta(n) {
  const note = chartRange !== 'recent' && rangeNotes[chartRange + ':' + n.id];
  return HUB.historyMeta(n) + (note ? `<div class="sparkMeta"><span>${esc(note)}</span></div>` : '');
}

function emptyHistoryText(n) {
  if (chartRange === 'recent') return '<div>No recent readings in the cloud for this device.</div>';
  const key = chartRange + ':' + n.id;
  return rangeRev[key] === undefined ? '<div>Loading…</div>'
    : `<div>No readings for this device in the last ${rangeName().toLowerCase()}.</div>`;
}

function setConnection(ok) {
  const el = document.getElementById('cloudStatus');
  if (!el) return;
  el.textContent = CLOUD.demo ? 'Sample data' : ok ? 'Cloud connected' : 'Cloud unavailable';
  el.className = 'cloudState ' + (CLOUD.demo ? 'demo' : ok ? 'ok' : 'down');
}

// ---------- Start ----------

(function start() {
  try { const r = localStorage.getItem('sentinelChartRange'); if (r && (r === 'recent' || RANGE_HOURS[r])) chartRange = r; } catch (e) {}
  document.getElementById('siteName').textContent = CLOUD.siteId;
  document.getElementById('hubName').textContent = CLOUD.hubId;
  setConnection(true);
  refresh();
  setInterval(refresh, CLOUD.refreshMs);
  // Keep "Xs ago" and online/late current between cloud refreshes, without a request.
  setInterval(() => {
    if (!latestNodes.length) return;
    latestNodes = buildNodes();
    refreshAges();
    renderMiniCards();
  }, 15000);
})();
